"""CLI commands for auto-generated files."""

from __future__ import annotations

import uuid

import click

from ai.backend.client.cli.v2.helpers import (
    create_v2_registry,
    load_v2_config,
    parse_order_options,
    print_result,
    run_async,
)
from ai.backend.common.dto.manager.v2.auto_generated_file.types import AutoGeneratedFileScopeType


@click.group()
def auto_generated_file() -> None:
    """Auto-generated file commands."""


@auto_generated_file.command()
@click.option(
    "--scope-type",
    required=True,
    type=click.Choice([member.value for member in AutoGeneratedFileScopeType]),
    help="Kind of the scope the file belongs to.",
)
@click.option("--scope-id", required=True, type=click.UUID, help="Domain, project or user ID.")
@click.option("--path", required=True, help="Path the file is written to in a session.")
@click.option("--permission", required=True, help="Unix file permission in octal (e.g., 644).")
@click.option("--data", required=True, help="Content of the file.")
def create(scope_type: str, scope_id: uuid.UUID, path: str, permission: str, data: str) -> None:
    """Add a file that is not the default of its path."""
    from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
        AutoGeneratedFileScopeInput,
        CreateAutoGeneratedFileInput,
    )

    request = CreateAutoGeneratedFileInput(
        scope=AutoGeneratedFileScopeInput(
            scope_type=AutoGeneratedFileScopeType(scope_type), scope_id=scope_id
        ),
        path=path,
        permission=permission,
        data=data,
    )

    async def _run() -> None:
        registry = await create_v2_registry(load_v2_config())
        try:
            print_result(await registry.auto_generated_file.create(request))
        finally:
            await registry.close()

    run_async(_run)


@auto_generated_file.command(name="scoped-search")
@click.option("--domain", "domains", multiple=True, type=click.UUID, help="Domain ID (repeatable).")
@click.option(
    "--project", "projects", multiple=True, type=click.UUID, help="Project ID (repeatable)."
)
@click.option("--user", "users", multiple=True, type=click.UUID, help="User ID (repeatable).")
@click.option("--path-contains", default=None, help="Filter by path substring.")
@click.option(
    "--default/--not-default",
    "is_default",
    default=None,
    help="Filter by whether the file is the default of its path.",
)
@click.option("--limit", type=int, default=20, help="Maximum number of items to return.")
@click.option("--offset", type=int, default=0, help="Number of items to skip.")
@click.option(
    "--order-by", multiple=True, help="Order by field:direction (e.g., path:asc, created_at:desc)."
)
def scoped_search(
    domains: tuple[uuid.UUID, ...],
    projects: tuple[uuid.UUID, ...],
    users: tuple[uuid.UUID, ...],
    path_contains: str | None,
    is_default: bool | None,
    limit: int,
    offset: int,
    order_by: tuple[str, ...],
) -> None:
    """Search the files of the named domains, projects and users (OR across all of them)."""
    from ai.backend.common.dto.manager.query import StringFilter
    from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
        AutoGeneratedFileFilter,
        AutoGeneratedFileOrder,
        ScopedSearchAutoGeneratedFilesInput,
    )
    from ai.backend.common.dto.manager.v2.auto_generated_file.types import (
        AutoGeneratedFileOrderField,
        AutoGeneratedFileScope,
    )
    from ai.backend.common.dto.manager.v2.rbac.types import UUIDScope

    if not domains and not projects and not users:
        raise click.UsageError("Name at least one of --domain, --project or --user.")
    request = ScopedSearchAutoGeneratedFilesInput(
        scope=AutoGeneratedFileScope(
            domain=[UUIDScope(value=domain_id) for domain_id in domains] or None,
            project=[UUIDScope(value=project_id) for project_id in projects] or None,
            user=[UUIDScope(value=user_id) for user_id in users] or None,
        ),
        filter=AutoGeneratedFileFilter(
            path=StringFilter(contains=path_contains) if path_contains is not None else None,
            is_default=is_default,
        ),
        order=parse_order_options(order_by, AutoGeneratedFileOrderField, AutoGeneratedFileOrder)
        if order_by
        else None,
        limit=limit,
        offset=offset,
    )

    async def _run() -> None:
        registry = await create_v2_registry(load_v2_config())
        try:
            print_result(await registry.auto_generated_file.scoped_search(request))
        finally:
            await registry.close()

    run_async(_run)


@auto_generated_file.command(name="switch-default")
@click.argument("auto_generated_file_id", type=click.UUID)
@click.option(
    "--scope-type",
    required=True,
    type=click.Choice([member.value for member in AutoGeneratedFileScopeType]),
    help="Kind of the scope the file belongs to.",
)
@click.option("--scope-id", required=True, type=click.UUID, help="Domain, project or user ID.")
def switch_default(auto_generated_file_id: uuid.UUID, scope_type: str, scope_id: uuid.UUID) -> None:
    """Make AUTO_GENERATED_FILE_ID the default of its path in its scope."""
    from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID
    from ai.backend.common.dto.manager.v2.auto_generated_file.request import (
        AutoGeneratedFileScopeInput,
    )

    scope = AutoGeneratedFileScopeInput(
        scope_type=AutoGeneratedFileScopeType(scope_type), scope_id=scope_id
    )

    async def _run() -> None:
        registry = await create_v2_registry(load_v2_config())
        try:
            print_result(
                await registry.auto_generated_file.switch_default(
                    AutoGeneratedFileID(auto_generated_file_id), scope
                )
            )
        finally:
            await registry.close()

    run_async(_run)


@auto_generated_file.command()
@click.argument("auto_generated_file_id", type=click.UUID)
def purge(auto_generated_file_id: uuid.UUID) -> None:
    """Remove AUTO_GENERATED_FILE_ID. The default of a path is refused."""
    from ai.backend.common.data.entity.auto_generated_file import AutoGeneratedFileID

    async def _run() -> None:
        registry = await create_v2_registry(load_v2_config())
        try:
            print_result(
                await registry.auto_generated_file.purge(
                    AutoGeneratedFileID(auto_generated_file_id)
                )
            )
        finally:
            await registry.close()

    run_async(_run)
